<?php
class Alumno {
 private PDO $db;
 public function __construct(){ $this->db=db(); }
 public function login(string $correo): ?array { $s=$this->db->prepare("SELECT a.id,a.nombre,a.correo_institucional,a.`contraseña` AS password_hash,a.credito,a.estado,c.nombre AS carrera,c.apodo FROM alumnos a JOIN carreras c ON c.id=a.id_carrera WHERE a.correo_institucional=? LIMIT 1"); $s->execute([$correo]); $r=$s->fetch(); return $r?:null; }
 public function perfil(int $id): array { $s=$this->db->prepare('SELECT a.id,a.nombre,a.correo_institucional,a.credito,a.estado,c.nombre AS carrera,c.apodo FROM alumnos a JOIN carreras c ON c.id=a.id_carrera WHERE a.id=?'); $s->execute([$id]); return $s->fetch()?:[]; }
 public function resumen(int $id): array { $s=$this->db->prepare("SELECT COUNT(*) total, COALESCE(AVG(NULLIF(c.calificacion_final,0)),0) promedio FROM inscripciones i LEFT JOIN calificaciones c ON c.inscripcion=i.id WHERE i.alumno=?");$s->execute([$id]);$r=$s->fetch()?:['total'=>0,'promedio'=>0];$s=$this->db->prepare("SELECT COUNT(*) FROM asistencias x JOIN inscripciones i ON i.id=x.inscripcion WHERE i.alumno=? AND x.estatus IN ('asistencia','justificada')");$s->execute([$id]);$r['asistencias']=$s->fetchColumn();$s=$this->db->prepare("SELECT COALESCE(SUM(a.monto),0)-COALESCE((SELECT SUM(p.monto) FROM pagos p JOIN adeudos ax ON ax.id=p.adeudo WHERE ax.alumno=a.alumno),0) FROM adeudos a WHERE a.alumno=? AND a.estatus NOT IN ('cancelado')");$s->execute([$id]);$r['saldo']=max(0,(float)$s->fetchColumn());return $r; }
 public function materias(int $id): array { $q="SELECT m.nombre materia,m.clave,m.creditos,g.nombre grupo,p.nombre profesor,i.estatus,COALESCE(c.parcial1,'—') p1,COALESCE(c.parcial2,'—') p2,COALESCE(c.parcial3,'—') p3,c.calificacion_final final FROM inscripciones i JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia JOIN grupos g ON g.id=mp.grupo JOIN profesores p ON p.id=mp.profesor LEFT JOIN calificaciones c ON c.inscripcion=i.id WHERE i.alumno=? ORDER BY m.nombre";$s=$this->db->prepare($q);$s->execute([$id]);return $s->fetchAll(); }
 public function horarios(int $id): array { $q="SELECT m.nombre materia,g.nombre grupo,h.dia,h.hora_inicio,h.hora_fin,h.aula,p.nombre profesor FROM inscripciones i JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia JOIN grupos g ON g.id=mp.grupo JOIN profesores p ON p.id=mp.profesor JOIN horarios h ON h.asignacion=mp.id WHERE i.alumno=? ORDER BY FIELD(h.dia,'lunes','martes','miercoles','jueves','viernes','sabado'),h.hora_inicio";$s=$this->db->prepare($q);$s->execute([$id]);return $s->fetchAll(); }
 public function asistencias(int $id): array { $q="SELECT m.nombre materia,x.fecha,x.estatus,x.observaciones FROM asistencias x JOIN inscripciones i ON i.id=x.inscripcion JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia WHERE i.alumno=? ORDER BY x.fecha DESC LIMIT 200";$s=$this->db->prepare($q);$s->execute([$id]);return $s->fetchAll(); }
 public function pagos(int $id): array { $q="SELECT a.id,a.monto,a.fecha_generacion,a.fecha_vencimiento,a.estatus,cp.nombre concepto,COALESCE((SELECT SUM(p.monto) FROM pagos p WHERE p.adeudo=a.id),0) pagado FROM adeudos a JOIN conceptos_pago cp ON cp.id=a.concepto WHERE a.alumno=? ORDER BY a.fecha_vencimiento DESC";$s=$this->db->prepare($q);$s->execute([$id]);return $s->fetchAll(); }
 public function cambiarPassword(int $id,string $hash): void { $s=$this->db->prepare('UPDATE alumnos SET `contraseña`=? WHERE id=?');$s->execute([$hash,$id]); }
 public function validarPassword(int $id): ?string { $s=$this->db->prepare('SELECT `contraseña` FROM alumnos WHERE id=?');$s->execute([$id]);$v=$s->fetchColumn();return $v===false?null:$v; }
}
